CREATE TABLE ablation_studies(study_name VARCHAR, config_name VARCHAR, rep INTEGER, params_json JSON, run_id VARCHAR, FOREIGN KEY (run_id) REFERENCES context(run_id), PRIMARY KEY(study_name, config_name, rep));
CREATE TABLE benchmarks(run_id VARCHAR, "name" VARCHAR, family_index INTEGER, per_family_instance_index INTEGER, run_type VARCHAR, repetitions INTEGER, repetition_index INTEGER, threads INTEGER, iterations BIGINT, real_time DOUBLE, cpu_time DOUBLE, time_unit VARCHAR, kv_g VARCHAR, kv_n VARCHAR, kv_t VARCHAR, kv_raw_params VARCHAR, run_name VARCHAR, L1_icache_load_misses DOUBLE, L1_icache_loads DOUBLE, branch_misses DOUBLE, cpu_cycles DOUBLE, iTLB_load_misses DOUBLE, instructions DOUBLE, allocs_per_iter DOUBLE, max_bytes_used BIGINT, jit_blob_kb DOUBLE, jit_module_fns DOUBLE, jit_module_instrs DOUBLE, jit_pruned_fns DOUBLE, jit_pruned_instrs DOUBLE, expected_call_ns DOUBLE, budget_fixpoint DOUBLE, budget_scale DOUBLE, budget_unroll DOUBLE, kv_s VARCHAR, kv_a VARCHAR, FOREIGN KEY (run_id) REFERENCES context(run_id), PRIMARY KEY(run_id, "name"));
CREATE TABLE context(run_id VARCHAR PRIMARY KEY, run_ts TIMESTAMP NOT NULL, git_sha VARCHAR, date VARCHAR, host_name VARCHAR, executable VARCHAR, num_cpus INTEGER, mhz_per_cpu INTEGER, cpu_scaling_enabled BOOLEAN, library_version VARCHAR, library_build_type VARCHAR, best_practice_full BOOLEAN);
CREATE TABLE optim_trial_params(study_name VARCHAR, trial_id INTEGER, run_id VARCHAR, params_json JSON NOT NULL, used_timeout_fallback BOOLEAN, obj_jit_ns DOUBLE, obj_exec_ns DOUBLE, obj_combined_ns DOUBLE, FOREIGN KEY (run_id) REFERENCES context(run_id), PRIMARY KEY(study_name, trial_id));
CREATE TABLE optimization_sessions(study_name VARCHAR PRIMARY KEY, "binary" VARCHAR, n_trials INTEGER, started_at TIMESTAMP, completed_at TIMESTAMP, status VARCHAR, search_space_json JSON);
CREATE TABLE pass_traces(run_id VARCHAR NOT NULL, benchmark_name VARCHAR NOT NULL, pass_idx INTEGER NOT NULL, pass_name VARCHAR, pass_group VARCHAR, fixpoint_iter INTEGER, fns_before BIGINT, fns_after BIGINT, instrs_before BIGINT, instrs_after BIGINT, bbs_before BIGINT, bbs_after BIGINT, wall_time_ms DOUBLE, ir_changed BOOLEAN, FOREIGN KEY (run_id) REFERENCES context(run_id));
CREATE TABLE unspec_baselines(study_name VARCHAR, kernel VARCHAR, unspec_ns DOUBLE NOT NULL, PRIMARY KEY(study_name, kernel));
CREATE VIEW v_ablation_medians AS SELECT study_name, config_name, kernel, "group", quantile_cont(0.5 ORDER BY t_jit_ns) AS med_jit_ns, quantile_cont(0.5 ORDER BY t_spec_ns) AS med_spec_ns, quantile_cont(0.5 ORDER BY t_unspec_ns) AS med_unspec_ns, count_star() AS n_reps FROM v_ablation_results GROUP BY study_name, config_name, kernel, "group";
CREATE VIEW v_ablation_results AS SELECT a.study_name, a.config_name, a.rep, a.params_json, r.kernel, r."group", r.t_jit_ns, r.t_spec_ns, r.t_unspec_ns FROM ablation_studies AS a INNER JOIN v_ratios AS r USING (run_id);
CREATE VIEW v_budget_sweep AS SELECT run_id, kernel, "group", git_sha, run_ts, kv_raw_params, CAST(split_part(kv_raw_params, '/', 2) AS INTEGER) AS scale_bp, real_time_ns, phase, expected_call_ns, budget_scale, budget_fixpoint, budget_unroll FROM v_ns WHERE (phase IN ('jit_budget_sweep', 'exec_budget_sweep'));
CREATE VIEW v_jit_stats AS SELECT run_id, kernel, raw_params, "group", jit_module_fns, jit_module_instrs, jit_blob_kb, jit_pruned_fns, jit_pruned_instrs, max_bytes_used FROM v_parsed WHERE ((phase = 'jit_overhead') AND (run_type = 'iteration'));
CREATE VIEW v_ns AS SELECT *, (real_time * CASE  WHEN ((time_unit = 'ns')) THEN (1.0) WHEN ((time_unit = 'us')) THEN (1000.0) WHEN ((time_unit = 'ms')) THEN (1000000.0) WHEN ((time_unit = 's')) THEN (1000000000.0) ELSE NULL END) AS real_time_ns FROM v_parsed WHERE (phase != '');
CREATE VIEW v_optim_best_per_kernel AS SELECT DISTINCT ON (ob.study_name, ob.kernel) ob.study_name, ob.trial_id, ob.kernel, ob.params_json, ob.t_jit_ns, ob.t_spec_ns, ob.unspec_ns, (ob.t_jit_ns + ob.t_spec_ns) AS total_ns, ob.break_even_calls FROM (SELECT *, (t_jit_ns + t_spec_ns) AS _total FROM v_optim_breakeven) AS ob INNER JOIN optimization_sessions AS os USING (study_name) WHERE (os.status = 'complete') ORDER BY ob.study_name, ob.kernel, ob._total;
CREATE VIEW v_optim_breakeven AS SELECT *, CASE  WHEN ((unspec_ns > t_spec_ns)) THEN ((t_jit_ns / (unspec_ns - t_spec_ns))) ELSE NULL END AS break_even_calls FROM v_optim_results;
CREATE VIEW v_optim_results AS SELECT otp.study_name, otp.trial_id, otp.params_json, otp.used_timeout_fallback, r.kernel, r."group", r.t_jit_ns, r.t_spec_ns, u.unspec_ns FROM optim_trial_params AS otp INNER JOIN v_ratios AS r USING (run_id) LEFT JOIN unspec_baselines AS u ON (((u.study_name = otp.study_name) AND (u.kernel = r.kernel)));
CREATE VIEW v_parsed AS SELECT b.*, c.git_sha, c.run_ts, c.host_name, b.kv_t AS phase, b.kv_n AS kernel, b.kv_g AS "group", b.kv_raw_params AS raw_params FROM benchmarks AS b INNER JOIN context AS c USING (run_id);
CREATE VIEW v_ratios AS SELECT run_id, kernel, raw_params, "group", git_sha, run_ts, host_name, max(CASE  WHEN ((phase = 'unspecialized')) THEN (real_time_ns) ELSE NULL END) AS t_unspec_ns, max(CASE  WHEN ((phase = 'specialized_exec')) THEN (real_time_ns) ELSE NULL END) AS t_spec_ns, max(CASE  WHEN ((phase = 'jit_overhead')) THEN (real_time_ns) ELSE NULL END) AS t_jit_ns FROM v_ns GROUP BY run_id, kernel, raw_params, "group", git_sha, run_ts, host_name;
